from __future__ import annotations


DASHBOARD_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Git-Hunter Admin Center</title>
<style>
:root{--bg:#08111f;--panel:#101d31;--panel2:#14253d;--line:#263c5c;--text:#edf4ff;--muted:#91a5c2;--blue:#57a1ff;--green:#32d583;--orange:#fdb022;--red:#f97066}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,sans-serif}
button,input,textarea,select{font:inherit}button{border:0;border-radius:7px;padding:9px 14px;color:#fff;background:#29466e;cursor:pointer;font-weight:650}
button:hover{filter:brightness(1.15)}button.primary{background:#1769d2}button.danger{background:#9e2f3e}button.ghost{background:transparent;border:1px solid var(--line)}
.shell{display:grid;grid-template-columns:245px 1fr;min-height:100vh}.side{background:#0b1729;border-right:1px solid var(--line);padding:24px 16px}
.brand{font-size:20px;font-weight:800;letter-spacing:-.03em;padding:0 10px 24px}.brand span{color:var(--blue)}
.nav{display:grid;gap:6px}.nav button{text-align:left;background:transparent;color:var(--muted);font-weight:600}.nav button.active,.nav button:hover{background:#162b49;color:var(--text)}
.side-footer{position:fixed;bottom:18px;color:var(--muted);font-size:12px;padding:0 10px}.main{min-width:0}.topbar{height:76px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;padding:0 30px}
.title h1{font-size:20px;margin:0 0 4px}.title p{margin:0;color:var(--muted)}.actions{display:flex;gap:8px;align-items:center}.pill{border-radius:999px;padding:5px 10px;background:#193454;color:var(--muted);font-size:12px}.pill.on{color:#7df2b1;background:#113c32}
.content{padding:28px 30px;max-width:1500px}.view{display:none}.view.active{display:block}.grid{display:grid;gap:14px}.metrics{grid-template-columns:repeat(5,minmax(130px,1fr));margin-bottom:18px}.two{grid-template-columns:1.35fr 1fr}.three{grid-template-columns:repeat(3,1fr)}
.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:18px}.metric .label,.label{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.07em}.metric .value{font-size:26px;font-weight:800;margin-top:8px}.muted{color:var(--muted)}.good{color:var(--green)}.warn{color:var(--orange)}.bad{color:var(--red)}
.card-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.card h2{font-size:15px;margin:0}.bar{height:8px;background:#1c2c45;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:var(--blue);border-radius:inherit;width:0;transition:width .3s}
.repo-name{font-size:22px;font-weight:800;margin:4px 0}.stage{color:var(--blue);font-weight:700}.kv{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #1d304b}.kv:last-child{border:0}
.code{background:#07101d;border:1px solid #1e3453;border-radius:7px;overflow:auto;max-height:300px;padding:14px;white-space:pre;font:12px ui-monospace,SFMono-Regular,monospace;color:#c7daf7}.files{max-height:170px;overflow:auto}.file{padding:5px 0;color:#a8c0df;border-bottom:1px solid #1b2c45}
.feed{max-height:280px;overflow:auto}.event{padding:9px 0;border-bottom:1px solid #1d304b}.event small{display:block;color:var(--muted);margin-top:3px}
.queue-item{display:flex;justify-content:space-between;align-items:center;padding:14px 0;border-bottom:1px solid #1d304b}.queue-item h3{margin:0 0 5px;font-size:15px}.score{border-radius:999px;padding:4px 9px;background:#632d3a;color:#ffb4ad;font-weight:800}.score.low{background:#164f42;color:#8ff0c0}
form{display:grid;gap:14px}.field{display:grid;gap:6px}.field label{font-weight:650}.hint{font-size:12px;color:var(--muted)}input,textarea,select{width:100%;padding:10px;border-radius:7px;border:1px solid var(--line);background:#091526;color:var(--text)}textarea{min-height:100px;resize:vertical}.form-actions{display:flex;gap:8px}
.notice{padding:12px;border-radius:7px;background:#192d49;color:#b9d4f5;margin-bottom:14px}.notice.warn{background:#3d3015;color:#ffdc8a}
@media(max-width:900px){.shell{grid-template-columns:1fr}.side{position:static;border-right:0;border-bottom:1px solid var(--line);padding:12px}.brand{padding:8px}.nav{display:flex;overflow:auto}.side-footer{display:none}.topbar{padding:0 16px}.content{padding:18px 16px}.metrics,.two,.three{grid-template-columns:1fr 1fr}.metrics .metric:last-child{grid-column:span 2}}
</style>
</head>
<body>
<div class="shell"><aside class="side"><div class="brand">Git<span>Hunter</span><br><small class="muted">Admin Center</small></div>
<nav class="nav"><button class="active" data-view="overview">◈ Overview</button><button data-view="analysis">◉ Live Analysis</button><button data-view="queue">☷ Review Queue</button><button data-view="targets">⌁ Targets</button><button data-view="settings">⚙ Settings</button></nav>
<div class="side-footer">Local control plane<br><span id="version">Connecting…</span></div></aside>
<section class="main"><header class="topbar"><div class="title"><h1 id="page-title">Operations overview</h1><p id="page-subtitle">Monitor and control your analysis fleet</p></div><div class="actions"><span id="system-pill" class="pill">● Stopped</span><button class="primary" id="toggle">Start system</button></div></header>
<main class="content">
<section id="overview" class="view active"><div class="grid metrics">
<div class="card metric"><div class="label">Pending</div><div class="value" id="m-pending">—</div></div><div class="card metric"><div class="label">Completed</div><div class="value good" id="m-completed">—</div></div><div class="card metric"><div class="label">In review</div><div class="value warn" id="m-review">—</div></div><div class="card metric"><div class="label">Failed</div><div class="value bad" id="m-failed">—</div></div><div class="card metric"><div class="label">API remaining</div><div class="value" id="m-api">—</div></div></div>
<div class="grid two"><div class="card"><div class="card-head"><h2>Current operation</h2><button class="ghost" data-view-link="analysis">Open details</button></div><div id="overview-current"><p class="muted">No repository is being analyzed.</p></div></div><div class="card"><div class="card-head"><h2>System health</h2><span id="latency" class="pill">—</span></div><div class="kv"><span>Spider discovery</span><strong id="spider">—</strong></div><div class="kv"><span>Analysis worker</span><strong id="worker">—</strong></div><div class="kv"><span>Configuration</span><strong id="config-state">—</strong></div><div class="kv"><span>Last event</span><strong id="last-event">—</strong></div></div></div>
<div class="grid two" style="margin-top:14px"><div class="card"><div class="card-head"><h2>Activity feed</h2><button class="ghost" onclick="loadAll()">Refresh</button></div><div id="feed" class="feed"></div></div><div class="card"><div class="card-head"><h2>Quick controls</h2></div><p class="muted">Pause both the Wanderer and analysis worker immediately, or resume the configured flow.</p><div class="actions"><button class="primary" onclick="system('start')">Start all</button><button class="danger" onclick="system('stop')">Stop all</button></div></div></div></section>
<section id="analysis" class="view"><div id="analysis-empty" class="card"><h2>No active analysis</h2><p class="muted">Start the system or wait for the worker to claim a repository.</p></div><div id="analysis-live" style="display:none"><div class="grid two"><div class="card"><div class="label">Repository currently being checked</div><div class="repo-name" id="a-repo">—</div><a id="a-url" target="_blank" class="muted">Open on GitHub ↗</a><p class="stage" id="a-stage">—</p><div class="bar"><i id="a-progress"></i></div><p class="muted" id="a-message"></p></div><div class="card"><div class="label">Analysis facts</div><div class="kv"><span>Files discovered</span><strong id="a-files">—</strong></div><div class="kv"><span>Current score</span><strong id="a-score">—</strong></div><div class="kv"><span>Queue id</span><strong id="a-id">—</strong></div></div></div><div class="grid two" style="margin-top:14px"><div class="card"><div class="card-head"><h2>Code currently in memory</h2><span class="pill">Read-only preview</span></div><pre class="code" id="a-code">Waiting for source fetch…</pre></div><div class="card"><div class="card-head"><h2>Repository codebase</h2><span id="a-file-count" class="pill">0 files</span></div><div id="a-file-list" class="files"></div></div></div></div></section>
<section id="queue" class="view"><div class="card"><div class="card-head"><h2>Review queue</h2><span class="muted">High-confidence reports awaiting a decision</span></div><div id="queue-list"></div></div></section>
<section id="targets" class="view"><div class="card"><div class="card-head"><h2>Discovery targets</h2><button class="primary" onclick="saveConfig()">Save targets</button></div><div class="grid two"><div class="field"><label>Search seed</label><input id="seed-query"><span class="hint">Use <strong>random</strong> for rotating CVE, PoC, and Python searches, or enter a GitHub search expression.</span></div><div class="field"><label>Repositories per discovery cycle</label><input id="max-repos" type="number" min="1" max="100"></div></div><div class="field" style="margin-top:14px"><label>Target file extensions</label><textarea id="extensions"></textarea><span class="hint">One extension per line. These files are fetched and analyzed.</span></div></div></section>
<section id="settings" class="view"><div class="notice">Secrets are held in process memory and are never written to the queue or results tables. Save credentials while the system is stopped, then start it from the top bar.</div><div class="card"><div class="card-head"><h2>Credentials & connections</h2><span id="cred-state" class="pill">Not configured</span></div><form onsubmit="saveSetup(event)"><div class="field"><label>GitHub personal access token</label><input id="github-token" type="password" placeholder="ghp_…"><span class="hint">Used for GitHub API discovery and source fetching. It is never displayed after saving.</span></div><div class="grid two"><div class="field"><label>Turso database URL</label><input id="turso-url" placeholder="libsql://…"><span class="hint">Optional when using the local development database.</span></div><div class="field"><label>Turso auth token</label><input id="turso-token" type="password" placeholder="Paste token"><span class="hint">Held only in process memory and applied immediately; it is never returned by the API.</span></div></div><div class="form-actions"><button class="primary">Save credentials</button><button type="button" class="ghost" onclick="loadSetup()">Discard</button></div></form></div><div class="card" style="margin-top:14px"><h2>Runtime behavior</h2><div class="field"><label>Worker scan interval (seconds)</label><input id="interval" type="number" min="1"></div><p class="hint">The worker waits this long between repositories. Changes apply immediately.</p><button class="primary" onclick="saveConfig()">Save runtime settings</button></div></section>
</main></section></div>
<script>
const $=id=>document.getElementById(id), views=[...document.querySelectorAll('.view')], events=[];
const stageProgress={fetching:18,analyzing:52,enriching:82,completed:100,failed:100};
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function show(view){views.forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={overview:['Operations overview','Monitor and control your analysis fleet'],analysis:['Live analysis','Inspect the repository and code currently in memory'],queue:['Review queue','Review anomaly reports and quarantine decisions'],targets:['Discovery targets','Control what the Wanderer searches for'],settings:['Settings','Configure credentials and runtime behavior']};$('page-title').textContent=titles[view][0];$('page-subtitle').textContent=titles[view][1]}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-view-link]').forEach(b=>b.onclick=()=>show(b.dataset.viewLink));
async function get(path){const r=await fetch(path);if(!r.ok)throw Error(await r.text());return r.json()}
async function system(action){const r=await fetch('/api/system/'+action,{method:'POST'});if(!r.ok){alert((await r.text()).replace(/<[^>]+>/g,''));return}await loadAll()}
async function loadStatus(){const s=await get('/api/system/status');const q=s.queue;['pending','completed','review','failed'].forEach(k=>{const key=k==='review'?'reviewed':k;$('m-'+k).textContent=q[key]??0});$('m-api').textContent=s.github_rate_limit_remaining??'—';$('spider').textContent=s.spider_state;$('worker').textContent=s.worker_state;$('latency').textContent=s.turso_latency_ms+' ms';$('config-state').textContent=s.github_token_configured?'Ready':'Needs token';$('last-event').textContent=s.last_event||'—';const on=s.spider_state==='running'||s.worker_state==='running';$('system-pill').textContent=on?'● Running':'● Stopped';$('system-pill').className='pill '+(on?'on':'');$('toggle').textContent=on?'Stop system':'Start system';$('toggle').onclick=()=>system(on?'stop':'start');return s}
function renderCurrent(c){const active=c&&c.repo_id; $('analysis-empty').style.display=active?'none':'block';$('analysis-live').style.display=active?'block':'none';if(!active){$('overview-current').innerHTML='<p class="muted">No repository is being analyzed.</p>';return}$('a-repo').textContent=c.full_name;$('a-url').href='https://github.com/'+c.full_name;$('a-stage').textContent=(c.stage||'queued').toUpperCase();$('a-progress').style.width=(stageProgress[c.stage]||8)+'%';$('a-message').textContent=c.message||'';$('a-files').textContent=c.files_scanned??0;$('a-score').textContent=c.anomaly_score??'—';$('a-id').textContent=c.repo_id;$('a-code').textContent=c.source_preview||'Fetching source preview…';$('a-file-count').textContent=(c.source_paths||[]).length+' files';$('a-file-list').innerHTML=(c.source_paths||[]).map(f=>'<div class="file">'+esc(f)+'</div>').join('')||'<span class="muted">Waiting for repository tree…</span>';$('overview-current').innerHTML='<div class="repo-name">'+esc(c.full_name)+'</div><p class="stage">'+esc(c.message||c.stage)+'</p><div class="bar"><i style="width:'+(stageProgress[c.stage]||8)+'%"></i></div><p class="muted">'+(c.files_scanned||0)+' files discovered</p>'}
async function loadCurrent(){renderCurrent(await get('/api/system/current'))}
async function loadQueue(){const rs=await get('/api/reports');$('queue-list').innerHTML=rs.length?rs.map(r=>'<div class="queue-item"><div><h3>'+esc(r.full_name)+'</h3><span class="muted">'+esc(r.status)+'</span></div><div class="actions"><span class="score '+(r.anomaly_score<75?'low':'')+'">'+r.anomaly_score+'</span><button class="ghost" onclick="review('+r.id+',\'safe\')">Mark safe</button><button class="danger" onclick="review('+r.id+',\'malicious_confirmed\')">Confirm malicious</button></div></div>').join(''):'<p class="muted">No reports awaiting review.</p>'}
async function review(id,status){await fetch('/api/review/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});loadQueue();loadStatus()}
async function loadConfig(){const c=await get('/api/config');$('interval').value=c.scan_interval_seconds;$('extensions').value=c.target_extensions.join('\\n');$('seed-query').value=c.seed_query;$('max-repos').value=c.max_repositories_per_cycle}
async function saveConfig(){await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scan_interval_seconds:Number($('interval').value),target_extensions:$('extensions').value.split('\\n').map(x=>x.trim()).filter(Boolean),seed_query:$('seed-query').value,max_repositories_per_cycle:Number($('max-repos').value)})});loadConfig()}
async function loadSetup(){const s=await get('/api/setup');$('cred-state').textContent=s.github_token_configured?'GitHub token configured':'GitHub token missing';$('cred-state').className='pill '+(s.github_token_configured?'on':'');$('turso-url').value=s.turso_database_url?.startsWith('file:')?'':(s.turso_database_url||'')}
async function saveSetup(e){e.preventDefault();const p={};if($('github-token').value)p.github_token=$('github-token').value;if($('turso-token').value)p.turso_auth_token=$('turso-token').value;if($('turso-url').value)p.turso_database_url=$('turso-url').value;const r=await fetch('/api/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});if(!r.ok){alert((await r.text()).replace(/<[^>]+>/g,''));return}$('github-token').value='';$('turso-token').value='';await loadSetup();await loadAll()}
async function loadFeed(){const f=await get('/api/activity');$('feed').innerHTML=f.map(x=>'<div class="event">'+esc(x.message)+'<small>'+esc(x.time)+'</small></div>').join('')||'<p class="muted">No events yet.</p>'}
async function loadAll(){try{await Promise.all([loadStatus(),loadCurrent(),loadQueue(),loadFeed()])}catch(e){console.error(e)}}
loadConfig();loadSetup();loadAll();setInterval(loadAll,3000);
</script></body></html>"""
